21		<style>
22			:root {
23				color-scheme: light dark;
24				--text: #1a1a1a;
25				--text-secondary: #555;
26				--background: #fff;
27				--accent: #0052a3;
28				--border: #e0e0e0;
29			}
30			@media (prefers-color-scheme: dark) {
31				:root {
32					--text: #e0e0e0;
33					--text-secondary: #a0a0a0;
34					--background: #121212;
35					--accent: #5fa3ff;
36					--border: #333;
37				}
38			}
39			*,
40			*::before,
41			*::after {
42				box-sizing: border-box;
43			}
44			html {
45				-webkit-text-size-adjust: 100%;
46				text-size-adjust: 100%;
47			}
48			@media (prefers-reduced-motion: no-preference) {
49				html {
50					scroll-behavior: smooth;
51				}
52				a {
53					transition: text-decoration-thickness 0.15s ease;
54				}
55				.skip-link {
56					transition: transform 0.15s ease;
57				}
58			}
59			body {
60				display: grid;
61				grid-template-rows: auto 1fr auto;
62				min-height: 100vh;
63				min-height: 100dvh;
64				font-family: system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
65				line-height: 1.6;
66				max-width: 70ch;
67				margin: 0 auto;
68				padding: max(1.25rem, env(safe-area-inset-top)) max(1.25rem, env(safe-area-inset-right)) max(1.25rem, env(safe-area-inset-bottom)) max(1.25rem, env(safe-area-inset-left));
69				color: var(--text);
70				background: var(--background);
71			}
72			h1 {
73				color: var(--accent);
74				font-size: 2rem;
75				line-height: 1.2;
76				text-wrap: balance;
77				margin: 0;
78			}
79			p {
80				text-wrap: pretty;
81				margin: 1rem 0;
82			}
83			a {
84				color: var(--accent);
85				text-underline-offset: 0.15em;
86				text-decoration-thickness: 1.5px;
87			}
88			a:hover {
89				text-decoration-thickness: 3px;
90			}
91			:focus-visible {
92				outline: 2px solid var(--accent);
93				outline-offset: 2px;
94			}
95			.skip-link {
96				position: absolute;
97				left: 0;
98				top: 0;
99				transform: translateY(-100%);
100				background: var(--accent);
101				color: var(--background);
102				padding: 0.75rem 1.5rem;
103				z-index: 1;
104				border-radius: 0 0 0.25rem 0;
105			}
106			.skip-link:focus {
107				transform: none;
108				outline-color: var(--text);
109			}
110			header {
111				padding-block: 1.5rem;
112				margin-bottom: 1.5rem;
113			}
114			main:focus {
115				outline: none;
116			}
117			footer {
118				padding-block: 1.5rem;
119				margin-top: 3rem;
120				border-top: 1px solid var(--border);
121				font-size: 0.875rem;
122				color: var(--text-secondary);
123			}
124			footer p {
125				margin: 0.5rem 0;
126			}
127			@media print {
128				.skip-link {
129					display: none;
130				}
131				body {
132					display: block;
133					min-height: 0;
134					max-width: none;
135				}
136			}
137		</style>
138	</head>
